using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Godot;
using RingworldTechDemo.Voxel.Core;
using RingworldTechDemo.Voxel.Phase2;
using RingworldTechDemo.Voxel.LOD;

namespace RingworldTechDemo.Terrain.Editable;

/// <summary>Opt-in sparse construction layer. It never samples, stores, or meshes natural terrain.</summary>
public partial class SmoothConstructionOverlay : Node3D
{
    [Export] public NodePath SourceGridPath { get; set; } = new();
    [Export] public int MaxWorkers { get; set; } = 2;
    [Export] public int MaxInstallsPerFrame { get; set; } = 2;
    [Export] public string RayHitGroup { get; set; } = "smooth_construction_overlay";
    private readonly Dictionary<SmoothConstructionBlock,SmoothConstructionMaterial> _blocks=new(); private readonly List<SmoothConstructionCommand> _commands=new();
    private readonly Dictionary<SmoothConstructionChunk,Entry> _entries=new(); private readonly Queue<Presenter> _pool=new(); private readonly ConcurrentQueue<Result> _ready=new(); private readonly HashSet<Task> _tasks=new(); private readonly object _taskGate=new();
    private VoxelChunkGridManager? _source; private RingLodGeometrySnapshot _geometry; private SemaphoreSlim? _workers; private CancellationTokenSource _cancel=new(); private bool _stopping;
    private ulong _revision, _generation, _nextId=1, _nextSequence=1; private int _active, _maxActive, _created, _reused, _stale, _cancelled; private long _installCount; private TaskCompletionSource _shutdown=new(TaskCreationOptions.RunContinuationsAsynchronously);
    private RingGrassExclusionSnapshot? _grassExclusionSnapshot;
    public bool SuspendInstallsForTests { get; set; }
    public int BlockCount=>_blocks.Count; public int PresenterCount=>_entries.Count; public int PoolCount=>_pool.Count; public int ActiveWorkers=>Volatile.Read(ref _active); public int MaxActiveWorkers=>_maxActive; public int CreatedPresenterCount=>_created; public int ReusedPresenterCount=>_reused; public int StaleResults=>_stale; public int Cancelled=>_cancelled; public ulong Revision=>_revision; public int ReadyResultCount=>_ready.Count; public int TaskCount { get { lock(_taskGate)return _tasks.Count; } } public long InstallCount=>_installCount; public long EstimatedBytes{get{long x=0;foreach(var e in _entries.Values)x+=e.Presenter.RetainedByteSize;return x;}} public int Pending=>TaskCount+ReadyResultCount; public Task AwaitShutdownForTestsAsync()=>_shutdown.Task;
    public bool IsQuiescent=>TaskCount==0&&ReadyResultCount==0&&ActiveWorkers==0;
    public readonly record struct DebugState(ulong Generation,bool Installed,ulong Hash,bool Opaque,bool Glass,bool Collision);
    public IReadOnlyDictionary<SmoothConstructionChunk,DebugState> CaptureDebugState(){var r=new Dictionary<SmoothConstructionChunk,DebugState>();foreach(var p in _entries)r[p.Key]=new(p.Value.Generation,p.Value.Installed,p.Value.Hash,p.Value.Presenter.HasOpaqueMesh,p.Value.Presenter.HasGlassMesh,p.Value.Presenter.HasCollision);return r;}
    public IReadOnlyDictionary<SmoothConstructionChunk,Vector3> CapturePresenterPositionsForTests(){var r=new Dictionary<SmoothConstructionChunk,Vector3>();foreach(var p in _entries)r[p.Key]=p.Value.Presenter.Position;return r;}
    public bool RebuildForTests(SmoothConstructionChunk c){if(!_entries.ContainsKey(c))return false;Rebuild(c);return true;}
    public override void _Ready(){_source=GetNodeOrNull<VoxelChunkGridManager>(SourceGridPath);if(_source==null){GD.PushWarning("SmoothConstructionOverlay needs SourceGridPath.");return;}_geometry=_source.CaptureLodGeometrySnapshot();_source.CanonicalFloatingOriginAnchorChanged+=OnGeometry;_workers=new SemaphoreSlim(Math.Max(1,MaxWorkers));}
    public override void _ExitTree(){_stopping=true;_cancel.Cancel();if(_source!=null)_source.CanonicalFloatingOriginAnchorChanged-=OnGeometry;foreach(var e in _entries.Values){e.Cancel.Cancel();e.Presenter.QueueFree();}while(_pool.Count>0)_pool.Dequeue().QueueFree();_entries.Clear();Task[] tasks;lock(_taskGate)tasks=new List<Task>(_tasks).ToArray();_=Task.WhenAll(tasks).ContinueWith(_=>{while(_ready.TryDequeue(out Result ignored)){} _workers?.Dispose();_cancel.Dispose();_shutdown.TrySetResult();},TaskScheduler.Default);}
    private void OnGeometry(RingLodGeometrySnapshot before,RingLodGeometrySnapshot current,RingCanonicalPosition anchor){_geometry=current;foreach(var p in _entries) p.Value.Presenter.Position=ChunkOrigin(p.Key);}
    public bool TryGetBlock(SmoothConstructionBlock block,out SmoothConstructionMaterial material){return _blocks.TryGetValue(Canonical(block),out material);}
    /// <summary>Captures a cached, immutable canonical occupancy view for grass worker tasks.</summary>
    public RingGrassExclusionSnapshot CaptureGrassExclusionSnapshot(){long around=Math.Max(1,AroundLength);if(_grassExclusionSnapshot!=null&&_grassExclusionSnapshot.Revision==_revision&&_grassExclusionSnapshot.AroundLength==around)return _grassExclusionSnapshot;var boxes=new List<RingGrassExclusionBox>(_blocks.Count);foreach(var block in _blocks.Keys)boxes.Add(new RingGrassExclusionBox(block.Around,block.Around+1d,block.Vertical,block.Vertical+1d,block.Across,block.Across+1d));return _grassExclusionSnapshot=new RingGrassExclusionSnapshot(_revision,around,boxes);}
    public IReadOnlyList<SmoothConstructionCommand> CaptureCommands()=>_commands.ToArray();
    public bool ReplaceCommands(IEnumerable<SmoothConstructionCommand> commands){if(_source==null)return false;try{var s=new SmoothConstructionSnapshot(commands,checked(_revision+1),AroundLength,AcrossWidth);var blocks=new Dictionary<SmoothConstructionBlock,SmoothConstructionMaterial>();ulong id=1,seq=1;foreach(var c in s.Ordered){if(c.Place)blocks[c.Block]=c.Material;else blocks.Remove(c.Block);id=Math.Max(id,checked(c.CommandId+1));seq=Math.Max(seq,checked(c.Sequence+1));}_blocks.Clear();foreach(var p in blocks)_blocks.Add(p.Key,p.Value);_commands.Clear();_commands.AddRange(s.Ordered);_revision=s.Revision;_nextId=id;_nextSequence=seq;RebuildAll();return true;}catch{return false;}}
    public bool TryPlaceBlockAtWorldPosition(Vector3 hit,Vector3 outwardNormal,SmoothConstructionMaterial material,out SmoothConstructionCommand command){command=default;if(_source==null||!Enum.IsDefined(material)||outwardNormal.LengthSquared()<.5f)return false;var p=_source.WorldToCanonicalRingPosition64(hit+outwardNormal.Normalized()*.51f);var b=Canonical(new SmoothConstructionBlock((long)Math.Floor(p.AroundMeters),(int)Math.Floor(p.VerticalMeters),(int)Math.Floor(p.AcrossMeters)));if(b.Across<0||b.Across>=AcrossWidth||_blocks.ContainsKey(b)||_nextId==ulong.MaxValue)return false;command=new SmoothConstructionCommand(1,_nextId++,_nextSequence++,true,b,material);Apply(command);return true;}
    public bool TryRemoveBlockAtWorldPosition(Vector3 hit,Vector3 outwardNormal,out SmoothConstructionCommand command){command=default;if(_source==null)return false;var p=_source.WorldToCanonicalRingPosition64(hit-outwardNormal.Normalized()*.01f);var b=Canonical(new SmoothConstructionBlock((long)Math.Floor(p.AroundMeters),(int)Math.Floor(p.VerticalMeters),(int)Math.Floor(p.AcrossMeters)));if(!_blocks.TryGetValue(b,out var material))return false;command=new SmoothConstructionCommand(1,_nextId++,_nextSequence++,false,b,material);Apply(command);return true;}
    public void Apply(SmoothConstructionCommand raw){if(_source==null)throw new InvalidOperationException("Overlay is not ready.");var all=new List<SmoothConstructionCommand>(_commands){raw};var validated=new SmoothConstructionSnapshot(all,checked(_revision+1),AroundLength,AcrossWidth);var blocks=new Dictionary<SmoothConstructionBlock,SmoothConstructionMaterial>();foreach(var command in validated.Ordered){if(command.Place)blocks[command.Block]=command.Material;else blocks.Remove(command.Block);}SmoothConstructionCommand target=default;foreach(var command in validated.Ordered)if(command.CommandId==raw.CommandId){target=command;break;}_commands.Clear();_commands.AddRange(validated.Ordered);_blocks.Clear();foreach(var p in blocks)_blocks.Add(p.Key,p.Value);_revision=validated.Revision;_nextId=Math.Max(_nextId,checked(raw.CommandId+1));_nextSequence=Math.Max(_nextSequence,checked(raw.Sequence+1));var affected=new HashSet<SmoothConstructionChunk>();foreach(var d in new[]{Vector3I.Zero,Vector3I.Right,Vector3I.Left,Vector3I.Up,Vector3I.Down,Vector3I.Forward,Vector3I.Back})affected.Add(Chunk(Canonical(new SmoothConstructionBlock(target.Block.Around+d.X,target.Block.Vertical+d.Y,target.Block.Across+d.Z))));foreach(var q in affected)Rebuild(q);}
    private void RebuildAll(){var chunks=new HashSet<SmoothConstructionChunk>();foreach(var b in _blocks.Keys)chunks.Add(Chunk(b));foreach(var old in new List<SmoothConstructionChunk>(_entries.Keys))chunks.Add(old);foreach(var c in chunks)Rebuild(c);}
    private void Rebuild(SmoothConstructionChunk c){if(_stopping||_source==null)return;if(_entries.TryGetValue(c,out var prior)){prior.Cancel.Cancel();_cancelled++;_entries.Remove(c);prior.Presenter.Reset();_pool.Enqueue(prior.Presenter);}if(!ContainsChunk(c)){return;}var p=_pool.Count>0?_pool.Dequeue():NewPresenter();if(_pool.Count>=0&&p.GetParent()!=null)_reused++;if(p.GetParent()==null)AddChild(p);p.Visible=true;p.Position=ChunkOrigin(c);ulong g=++_generation,rev=_revision;var entry=new Entry(p){Generation=g};_entries[c]=entry;var copy=new Dictionary<SmoothConstructionBlock,SmoothConstructionMaterial>(_blocks);var geometry=_geometry;var inverse=GlobalTransform.AffineInverse();var token=CancellationTokenSource.CreateLinkedTokenSource(_cancel.Token,entry.Cancel.Token);Task task=Task.Run(async()=>{bool held=false;try{await _workers!.WaitAsync(token.Token);held=true;int active=Interlocked.Increment(ref _active);while(true){int old=_maxActive;if(active<=old||Interlocked.CompareExchange(ref _maxActive,active,old)==old)break;}token.Token.ThrowIfCancellationRequested();var data=SmoothConstructionMesher.Build(c,copy,AroundLength,geometry,inverse);_ready.Enqueue(new Result(c,g,rev,data));}catch(OperationCanceledException){Interlocked.Increment(ref _cancelled);}finally{if(held){Interlocked.Decrement(ref _active);_workers!.Release();}token.Dispose();}});lock(_taskGate)_tasks.Add(task);_ = task.ContinueWith(t=>{lock(_taskGate)_tasks.Remove(t);},TaskScheduler.Default);}
    public override void _Process(double delta){if(SuspendInstallsForTests)return;for(int q=0;q<MaxInstallsPerFrame&&_ready.TryDequeue(out var r);q++){if(!_entries.TryGetValue(r.Chunk,out var e)||e.Generation!=r.Generation||r.Revision!=_revision){_stale++;continue;}e.Presenter.Install(r.Data);e.Presenter.AddToGroup(RayHitGroup);e.Installed=true;e.Hash=r.Data.Hash;_installCount++;}}
    private Presenter NewPresenter(){_created++;return new Presenter();}
    private bool ContainsChunk(SmoothConstructionChunk c){foreach(var b in _blocks.Keys)if(Chunk(b)==c)return true;return false;}
    private SmoothConstructionBlock Canonical(SmoothConstructionBlock b)=>b.Canonical(AroundLength);
    private long AroundLength=>(long)Math.Round(_geometry.CircumferenceMeters); private int AcrossWidth=>Math.Max(1,(int)Math.Round(_source!.RingAcrossWidthMeters));
    private static SmoothConstructionChunk Chunk(SmoothConstructionBlock b)=>new(FloorDiv(b.Around,32),(int)FloorDiv(b.Vertical,32),(int)FloorDiv(b.Across,32));
    private static long FloorDiv(long value,long divisor)=>value>=0?value/divisor:-((-value+divisor-1)/divisor);
    private Vector3 ChunkOrigin(SmoothConstructionChunk c)=>GlobalTransform.AffineInverse()*_geometry.CanonicalToWorld(c.AroundChunk*32,c.VerticalChunk*32,c.AcrossChunk*32);
    private sealed class Entry { public readonly Presenter Presenter; public readonly CancellationTokenSource Cancel=new(); public ulong Generation; public bool Installed; public ulong Hash; public Entry(Presenter p){Presenter=p;} }
    private readonly record struct Result(SmoothConstructionChunk Chunk,ulong Generation,ulong Revision,SmoothConstructionMeshData Data);
}

public sealed partial class Presenter : Node3D
{
    private readonly MeshInstance3D _opaque=new(),_glass=new();private readonly StaticBody3D _body=new();private readonly CollisionShape3D _shape=new();private Vector3[] _faces=Array.Empty<Vector3>();private long _bytes;
    private static readonly StandardMaterial3D Concrete=new(){AlbedoColor=new Color(.46f,.46f,.48f),Roughness=.9f}; private static readonly StandardMaterial3D Glass=new(){AlbedoColor=new Color(.55f,.8f,.95f,.38f),Transparency=BaseMaterial3D.TransparencyEnum.Alpha,CullMode=BaseMaterial3D.CullModeEnum.Disabled,DepthDrawMode=BaseMaterial3D.DepthDrawModeEnum.Always};
    public bool HasOpaqueMesh=>_opaque.Mesh!=null;public bool HasGlassMesh=>_glass.Mesh!=null;public bool HasCollision=>_shape.Shape!=null;public long RetainedByteSize=>_bytes;
    public Presenter(){AddChild(_opaque);AddChild(_glass);AddChild(_body);_body.AddChild(_shape);} public void Install(SmoothConstructionMeshData d){_faces=d.CollisionFaces;_opaque.Mesh=Make(d,false);_glass.Mesh=Make(d,true);_opaque.MaterialOverride=Concrete;_glass.MaterialOverride=Glass;_bytes=(long)d.Vertices.Length*28+(long)d.Indices.Length*4+(long)d.CollisionFaces.Length*12;if(_faces.Length>0){var s=new ConcavePolygonShape3D();s.Data=_faces;_shape.Shape=s;}else _shape.Shape=null;} public void Reset(){Visible=false;_opaque.Mesh=null;_glass.Mesh=null;_opaque.MaterialOverride=null;_glass.MaterialOverride=null;_shape.Shape=null;_faces=Array.Empty<Vector3>();_bytes=0;}
    private static ArrayMesh? Make(SmoothConstructionMeshData d,bool glass){var ids=new List<int>();for(int x=0;x<d.Indices.Length;x+=3)if((d.Materials[d.Indices[x]]==(int)SmoothConstructionMaterial.Glass)==glass)ids.AddRange(new[]{d.Indices[x],d.Indices[x+1],d.Indices[x+2]});if(ids.Count==0)return null;var a=new Godot.Collections.Array();a.Resize((int)Mesh.ArrayType.Max);a[(int)Mesh.ArrayType.Vertex]=d.Vertices;a[(int)Mesh.ArrayType.Normal]=d.Normals;a[(int)Mesh.ArrayType.Index]=ids.ToArray();var mesh=new ArrayMesh();mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles,a);return mesh;}
}
